const e=new Intl.NumberFormat("vi-VN",{maximumFractionDigits:0});function i(t){const r=Math.round(Number(t)||0);return`${e.format(r)}đ`}function m(t,r=2){const n=Number(t);return Number.isFinite(n)?new Intl.NumberFormat("vi-VN",{minimumFractionDigits:0,maximumFractionDigits:r}).format(n):"0"}function o(t){if(typeof t=="number")return Number.isFinite(t)?t:0;if(typeof t!="string")return 0;const r=t.trim().replace(/\s+/g,"").replace(",","."),n=Number.parseFloat(r);return Number.isFinite(n)?n:0}export{i as a,m as f,o as p};
